import { unstable_cache, revalidateTag } from 'next/cache';

// Mock product data fetcher
const getProducts = unstable_cache(
  async () => {
    // Simulate fetching from an external ERP/PIM system
    // In a real scenario, this would be a database query or API call
    const products = Array.from({ length: 50 }, (_, i) => ({
      id: `sku-${i + 1}`,
      name: `Product ${i + 1}`,
      price: Math.floor(Math.random() * 1000) + 100,
      inventory: Math.floor(Math.random() * 100),
      lastUpdated: new Date().toISOString(),
    }));

    // Simulate network latency
    await new Promise((resolve) => setTimeout(resolve, 500));

    return products;
  },
  ['products-list'], // key parts
  { tags: ['products'] } // revalidation tags
);

export default async function AdminProductsPage() {
  const products = await getProducts();

  async function syncCatalog() {
    'use server';
    // Trigger revalidation for the 'products' tag
    // This invalidates the cache, causing the next request to fetch fresh data
    revalidateTag('products');
  }

  return (
    <div className="p-8 font-sans">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Product Catalog</h1>
        <form action={syncCatalog}>
          <button 
            type="submit" 
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
          >
            Sync Latest Catalog
          </button>
        </form>
      </div>

      <div className="overflow-x-auto">
        <table className="min-w-full bg-white border border-gray-200">
          <thead>
            <tr className="bg-gray-50 border-b">
              <th className="text-left py-3 px-4 font-semibold text-gray-700">SKU</th>
              <th className="text-left py-3 px-4 font-semibold text-gray-700">Name</th>
              <th className="text-left py-3 px-4 font-semibold text-gray-700">Price</th>
              <th className="text-left py-3 px-4 font-semibold text-gray-700">Inventory</th>
              <th className="text-left py-3 px-4 font-semibold text-gray-700">Last Updated</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product.id} className="border-b hover:bg-gray-50">
                <td className="py-3 px-4 text-gray-600">{product.id}</td>
                <td className="py-3 px-4 font-medium text-gray-900">{product.name}</td>
                <td className="py-3 px-4 text-gray-600">${product.price}</td>
                <td className="py-3 px-4 text-gray-600">{product.inventory}</td>
                <td className="py-3 px-4 text-gray-500 text-sm">
                  {new Date(product.lastUpdated).toLocaleTimeString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p className="mt-4 text-sm text-gray-500">
        Total Products: {products.length}. cache-tag: "products"
      </p>
    </div>
  );
}

